synthetic-dom.raw:
- name: Actual Expense workflow with isolated synthetic inputs
  if: ${{ !cancelled() }}
  run: python scripts/qa_expense_adaptive.py

- name: Actual Purchase order workflow with isolated synthetic inputs
  if: ${{ !cancelled() }}
  run: python scripts/qa_po_adaptive.py

- name: Actual Monthly workflow with isolated synthetic inputs
  if: ${{ !cancelled() }}
  run: python scripts/qa_browser_diagnostics.py qa_monthly_adaptive.py

- name: Source correction links reach native controls and persist after reload
  if: ${{ !cancelled() }}
  run: python scripts/qa_source_corrections.py

- name: Fresh ordinary Monthly site pointer and keyboard from zero
  if: ${{ !cancelled() }}
  run: python scripts/qa_monthly_site_pointer.py

- name: Prepared-by correction link reaches the native field by pointer and keyboard
  if: ${{ !cancelled() }}
  run: python scripts/qa_monthly_preparer_navigation.py

- name: Native Training and issue text with real exports and deliberate clear/reentry
  if: ${{ !cancelled() }}
  run: python scripts/qa_monthly_text_hydration.py

- name: Shared fixture upload and actual Starting report workflow
  if: ${{ !cancelled() }}
  run: python scripts/qa_browser_diagnostics.py qa_shared_fixture_testing.py

- name: Shared logo single-record replacement, stale review and restore
  if: ${{ !cancelled() }}
  run: python scripts/qa_single_logo_admin.py

- name: Fresh ordinary Water page review from empty omitted state
  if: ${{ !cancelled() }}
  run: python scripts/qa_water_fresh_page_journey.py

synthetic-dom.before:
- name: Select explicitly requested one-shot native owner diagnostic
  id: native_owner_request
  if: ${{ !cancelled() && github.event_name == 'pull_request' && github.event.pull_request.number == 249 && github.run_attempt == 1 }}

synthetic-dom.raw:
- name: One separate diagnostic-only WebKit native observer owner capture
  if: ${{ !cancelled() && steps.native_owner_request.outputs.enabled == 'true' }}
  run: python scripts/qa_fresh_native_owner_diagnostic.py
